#!/usr/bin/env bash
# shellcheck disable=SC1087,SC2329 # library: "$e[" is no array; unused helpers
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
# Wisp host wizard: brings a new server to the production baseline (docs/new-host.md).
#
#   ops/wizard.sh setup      on the new server, as its admin user, from a checkout of main
#   ops/wizard.sh env        on the server: fills /etc/wisp/production.env, secrets by hidden input
#
# Root commands are shown exactly and run only when the owner says yes. Nothing here prints a secret.

REPO=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)

APP_ORIGIN=https://app.wispmoney.com
CALLBACK_PATH=/bank-connections/callback

# Installed paths (ops/README.md, Production).
SERVER_ENV=/etc/wisp/production.env
SERVER_BACKUP_ENV=/etc/wisp/backup.env
SERVER_RELEASE_ENV=/etc/wisp/release-trigger.env
SERVER_KEY=/etc/wisp/enable-banking-private.key
API_UID=10001

# shellcheck disable=SC2016 # expanded by the bash -c that runs it
HEALTH_WAIT='for _ in $(seq 60); do curl -fsS -o /dev/null http://127.0.0.1:8080/api/health && exit 0; sleep 5; done; exit 1'

# ── Helpers ───────────────────────────────────────────────────────────────

show_cmd() {
  printf '    %s$' "$BOLD"
  printf ' %q' "$@"
  printf '%s\n' "$RESET"
}

# root CMD...: shows the exact root command and runs it with sudo once the owner says yes.
root() {
  show_cmd sudo "$@"
  if confirm "Run this root command now?"; then
    sudo "$@"
  else
    pause "Run it yourself in another terminal, then press Enter"
  fi
}

# root_write PATH CONTENT: shows a root-owned file's content, then writes it once the owner says yes.
root_write() {
  local path=$1 content=$2
  say "Content of $path:"
  printf '%s\n' "$content" | sed 's/^/      /'
  show_cmd sudo tee "$path"
  if confirm "Write it as root now?"; then
    printf '%s\n' "$content" | sudo tee -- "$path" >/dev/null
  else
    pause "Write it yourself in another terminal, then press Enter"
  fi
}

fail_stop() {
  warn "$1"
  exit 1
}

# ask_bool KEY "Prompt": like ask, for true or false.
ask_bool() {
  while :; do
    ask "$1" "$2 (true/false):"
    [[ ${!1} == true || ${!1} == false ]] && return
    warn "type true or false"
  done
}

# default_env KEY VALUE: writes VALUE only when ENV_FILE has no KEY yet, so the owner's own value stays.
default_env() {
  [[ -n $(_existing "$1" || true) ]] || write_env "$1" "$2"
}

random_secret() { od -An -tx1 -N32 /dev/urandom | tr -d ' \n'; }

# Reads `ss -Htln` lines on stdin: true when something listens and only on Tailscale's ranges
# (100.64.0.0/10, fd7a:115c:a1e0::/48).
tailnet_only() {
  local addresses
  addresses=$(awk '{ print $4 }')
  [[ -n $addresses ]] &&
    ! grep -vqE '^(100\.(6[4-9]|[7-9][0-9]|1[01][0-9]|12[0-7])\.[0-9.]+|\[fd7a:115c:a1e0:[0-9a-f:]*\]):22$' <<<"$addresses"
}

# ── Server setup ──────────────────────────────────────────────────────────

setup_wizard() {
TOTAL_STAGES=16
banner "Wisp server setup"

stage "Check the server"
# shellcheck disable=SC1091
. /etc/os-release
[[ ${VERSION_ID:-} == 26.04 && $(uname -m) == x86_64 ]] || fail_stop "this is for Ubuntu 26.04 LTS on amd64; found ${PRETTY_NAME:-unknown} on $(uname -m)"
[[ $EUID != 0 ]] || fail_stop "run this as the admin user (with sudo rights), not root; see docs/new-host.md"
id -nG | grep -qw sudo || fail_stop "$USER is not in the sudo group"
git -C "$REPO" fetch -q origin main
if [[ -n $(git -C "$REPO" status --porcelain) || $(git -C "$REPO" rev-parse HEAD) != "$(git -C "$REPO" rev-parse origin/main)" ]]; then
  fail_stop "the checkout must be a clean origin/main: git -C $REPO checkout --detach origin/main"
fi
say "Ubuntu ${VERSION_ID} on amd64, admin user $USER, checkout at origin/main."
note "Each root command is shown first and runs only when you answer y. Re-running skips finished parts."
pause

stage "Packages"
packages=(docker.io docker-compose-v2 git curl jq nftables restic python3 unattended-upgrades)
if dpkg-query -W -f '${Status}\n' "${packages[@]}" 2>/dev/null | grep -vq 'install ok installed' ||
  (($(dpkg-query -W -f '${Status}\n' "${packages[@]}" 2>/dev/null | wc -l) < ${#packages[@]})); then
  say "Docker with Compose, and the tools the install, deploy, backup and egress scripts use, from Ubuntu's archive."
  root apt-get update
  root apt-get install -y "${packages[@]}"
else
  say "Already installed: ${packages[*]}."
fi
if ! id -nG | grep -qw docker || ! id -nG | grep -qw systemd-journal; then
  say "$USER joins docker (deploys and checks) and systemd-journal (checks read the drill's log)."
  root usermod -aG docker,systemd-journal "$USER"
  warn "Log out and back in so the groups apply, then run ops/wizard.sh setup again."
  exit 0
fi
pause

stage "Automatic security updates"
say "Security updates install daily; one that needs a reboot reboots at 04:00 server time,"
say "clear of the 02:23 UTC release and the 00:30 and 06:30 backups."
note "Server time zone: $(timedatectl show -p Timezone --value 2>/dev/null || echo unknown)"
if [[ -f /etc/apt/apt.conf.d/52wisp-unattended-upgrades ]]; then
  say "Already configured."
else
  root_write /etc/apt/apt.conf.d/20auto-upgrades 'APT::Periodic::Update-Package-Lists "1";
APT::Periodic::Unattended-Upgrade "1";'
  root_write /etc/apt/apt.conf.d/52wisp-unattended-upgrades '// Wisp production: reboot for updates that need it, at night (docs/new-host.md).
Unattended-Upgrade::Automatic-Reboot "true";
Unattended-Upgrade::Automatic-Reboot-WithUsers "true";
Unattended-Upgrade::Automatic-Reboot-Time "04:00";'
fi
pause

stage "Tailscale"
if ! command -v tailscale >/dev/null; then
  say "Tailscale's own package repository for Ubuntu ${VERSION_CODENAME}."
  tmp=$(mktemp -d)
  curl -fsSL "https://pkgs.tailscale.com/stable/ubuntu/${VERSION_CODENAME}.noarmor.gpg" -o "$tmp/tailscale.gpg"
  curl -fsSL "https://pkgs.tailscale.com/stable/ubuntu/${VERSION_CODENAME}.tailscale-keyring.list" -o "$tmp/tailscale.list"
  note "$(cat "$tmp/tailscale.list")"
  root install -m 644 "$tmp/tailscale.gpg" /usr/share/keyrings/tailscale-archive-keyring.gpg
  root install -m 644 "$tmp/tailscale.list" /etc/apt/sources.list.d/tailscale.list
  rm -rf -- "$tmp"
  root apt-get update
  root apt-get install -y tailscale
fi
if ! tailscale ip -4 >/dev/null 2>&1; then
  say "Log the server in to your tailnet: open the address tailscale prints."
  root tailscale up
fi
root tailscale set --auto-update
open_url "https://login.tailscale.com/admin/machines"
step "In the admin console: this server → ⋯ → Disable key expiry, so it stays on the tailnet."
pause "Done?"

stage "SSH on the tailnet only"
ts4=$(tailscale ip -4)
ts6=$(tailscale ip -6 2>/dev/null || true)
ts_name=$(tailscale status --json | jq -r '.Self.DNSName | rtrimstr(".")')
if ss -Htln 'sport = :22' | tailnet_only; then
  say "sshd already listens on tailnet addresses only."
else
say "sshd listens on $ts4${ts6:+ and $ts6} only, keys only, no root login."
root_write /etc/sysctl.d/60-wisp-ssh-tailnet.conf '# sshd binds the tailnet addresses before tailscale0 is up at boot (docs/new-host.md).
net.ipv4.ip_nonlocal_bind = 1
net.ipv6.ip_nonlocal_bind = 1'
root sysctl -q --system
root_write /etc/ssh/sshd_config.d/10-wisp-tailnet.conf "# SSH on the tailnet only; the Hetzner web console is the fallback (docs/new-host.md).
ListenAddress $ts4${ts6:+
ListenAddress $ts6}
PasswordAuthentication no
KbdInteractiveAuthentication no
PermitRootLogin no"
root sshd -t
if systemctl list-unit-files ssh.socket >/dev/null 2>&1 && systemctl is-enabled --quiet ssh.socket; then
  say "Ubuntu starts sshd from a socket by default; sshd binds its own addresses instead."
  root systemctl disable --now ssh.socket
  root rm -f /etc/systemd/system/ssh.service.d/00-socket.conf /etc/systemd/system/ssh.socket.d/addresses.conf
  root systemctl daemon-reload
  root systemctl enable ssh.service
fi
root systemctl restart ssh.service
say "sshd now listens on:"
ss -Htln 'sport = :22' | awk '{ print "      " $4 }'
warn "Keep this session open. From your own machine, in a new terminal: ssh $USER@$ts_name"
pause "Press Enter once that login works"
fi

stage "Hetzner firewall"
say "Apply with the write token (owner only). Inbound, nothing else:"
step "TCP 80 from 0.0.0.0/0 and ::/0 (HTTP, redirects to HTTPS and certificate checks)"
step "TCP 443 from 0.0.0.0/0 and ::/0 (HTTPS)"
step "No other inbound rule: remove any rule for port 22 now that SSH works over the tailnet."
step "No outbound rules (everything outbound allowed); apply the firewall to this server."
note "Console: Hetzner Console → the project → Firewalls → Create Firewall. With the hcloud CLI:"
note "  hcloud firewall create --name wisp-web"
note "  hcloud firewall add-rule wisp-web --direction in --protocol tcp --port 80 --source-ips 0.0.0.0/0 --source-ips ::/0"
note "  hcloud firewall add-rule wisp-web --direction in --protocol tcp --port 443 --source-ips 0.0.0.0/0 --source-ips ::/0"
note "  hcloud firewall apply-to-resource wisp-web --type server --server <server name>"
open_url "https://console.hetzner.com/"
pause "Applied?"

stage "DNS records"
ip4=$(ip -4 -o route get 1.1.1.1 | sed -n 's/.* src \([0-9.]*\).*/\1/p')
ip6=$(ip -6 -o route get 2606:4700:4700::1111 2>/dev/null | sed -n 's/.* src \([0-9a-f:]*\).*/\1/p' || true)
say "In Hetzner DNS, zone wispmoney.com (OVH's nameservers for the domain point at the ones Hetzner lists):"
step "app   A     $ip4"
[[ -z $ip6 ]] || step "app   AAAA  $ip6"
step "@     A     $ip4"
[[ -z $ip6 ]] || step "@     AAAA  $ip6"
step "@     TXT   the SPF record Scaleway shows (v=spf1 include:… for Scaleway)"
step "the DKIM TXT record Scaleway shows (name …._domainkey), value exactly as shown"
open_url "https://console.scaleway.com/transactional-email/domains"
note "Scaleway: Transactional Email → Domains → wispmoney.com lists the SPF and DKIM records to copy."
pause "Added? Press Enter to check the app's A record"
resolved=$(getent ahostsv4 app.wispmoney.com | awk 'NR == 1 { print $1 }' || true)
if [[ $resolved == "$ip4" ]]; then say "app.wispmoney.com resolves to this server."; else warn "app.wispmoney.com resolves to '${resolved:-nothing}' so far; Caddy retries until it points here."; fi
pause

stage "Directories"
say "The env files belong to $USER (mode 600): the deploy, backup and failure-email units run as $USER."
root install -d -m 755 /etc/wisp
[[ -e $SERVER_ENV ]] || root install -m 600 -o "$USER" -g "$USER" /dev/null "$SERVER_ENV"
[[ -e $SERVER_BACKUP_ENV ]] || root install -m 600 -o "$USER" -g "$USER" /dev/null "$SERVER_BACKUP_ENV"
[[ -e $SERVER_RELEASE_ENV ]] || root install -m 600 -o "$USER" -g "$USER" /dev/null "$SERVER_RELEASE_ENV"
[[ -d /var/lib/wisp-deploy ]] || root install -d -m 755 -o "$USER" -g "$USER" /var/lib/wisp-deploy
pause

stage "The production env file"
say "The env file part runs now; ops/wizard.sh env runs it again on its own."
pause
bash "$REPO/ops/wizard.sh" env

stage "The banking key"
if [[ -f $SERVER_KEY && $(stat -c '%U %g %a' "$SERVER_KEY") == "$USER $API_UID 440" ]]; then
  say "Already installed at $SERVER_KEY."
else
  say "Copy the Enable Banking private key from the owner's off-server copy:"
  step "From that machine: scp <key file> $USER@$ts_name:enable-banking-private.key"
  pause "Copied?"
  [[ -f $HOME/enable-banking-private.key ]] || fail_stop "no ~/enable-banking-private.key"
  say "It belongs to $USER and group $API_UID (the API's uid), mode 0440."
  root install -o "$USER" -g "$API_UID" -m 0440 "$HOME/enable-banking-private.key" "$SERVER_KEY"
  rm -f -- "$HOME/enable-banking-private.key"
fi
pause

stage "Off-site backups"
ENV_FILE=$SERVER_BACKUP_ENV
if [[ -z $(_existing RESTIC_REPOSITORY || true) ]]; then
  open_url "https://console.hetzner.com/"
  step "Storage Boxes → the Helsinki box: note its user (u + digits); turn on SSH support and automatic snapshots."
  ask STORAGE_BOX_USER "Storage Box user (such as u000000):"
  [[ $STORAGE_BOX_USER =~ ^u[0-9]+$ ]] || fail_stop "a Storage Box user looks like u000000"
  write_env RESTIC_REPOSITORY "sftp:$STORAGE_BOX_USER.your-storagebox.de:wisp"
fi
box=$(_existing RESTIC_REPOSITORY)
box=${box#sftp:}
box=${box%%:*}
[[ -f $HOME/.ssh/wisp-backup ]] || ssh-keygen -q -t ed25519 -f "$HOME/.ssh/wisp-backup" -N ''
if ! grep -qx "Host $box" "$HOME/.ssh/config" 2>/dev/null; then
  printf 'Host %s\n    User %s\n    Port 23\n    IdentityFile ~/.ssh/wisp-backup\n' "$box" "${box%%.*}" >>"$HOME/.ssh/config"
fi
if ! ssh -o BatchMode=yes -o ConnectTimeout=15 "$box" pwd >/dev/null 2>&1; then
  say "ssh asks for the Storage Box password once, to install the backup key:"
  ssh "$box" install-ssh-key <"$HOME/.ssh/wisp-backup.pub"
fi
if [[ -z $(_existing RESTIC_PASSWORD || true) ]]; then
  say "The restic password encrypts every backup. Keep a copy off the server: without it no backup restores."
  while :; do
    ask_secret RESTIC_PASSWORD "restic password (letters and digits, at least 24):"
    ask_secret RESTIC_PASSWORD_AGAIN "The same again:"
    [[ $RESTIC_PASSWORD =~ ^[A-Za-z0-9]{24,}$ ]] || { warn "use at least 24 letters and digits"; continue; }
    [[ $RESTIC_PASSWORD == "$RESTIC_PASSWORD_AGAIN" ]] && break
    warn "the two entries differ"
  done
  write_env RESTIC_PASSWORD "$RESTIC_PASSWORD"
  unset RESTIC_PASSWORD RESTIC_PASSWORD_AGAIN
fi
(
  set -a
  # shellcheck disable=SC1090
  . "$SERVER_BACKUP_ENV"
  set +a
  restic cat config >/dev/null 2>&1 || restic init
) || fail_stop "restic cannot open or create the repository"
ENV_FILE=$SERVER_ENV
pause

stage "Nightly release trigger"
ENV_FILE=$SERVER_RELEASE_ENV
say "Each night at 02:23 UTC the server starts the Release workflow on GitHub; it needs a token that can only start workflows."
if [[ -z $(_existing RELEASE_TRIGGER_TOKEN || true) ]]; then
  open_url "https://github.com/settings/personal-access-tokens/new"
  step "Fine-grained token: owner wispmoney, only the wisp repository, permission Actions: read and write, nothing else, expiry one year."
  ask_secret RELEASE_TRIGGER_TOKEN "The token:"
  [[ $RELEASE_TRIGGER_TOKEN =~ ^[A-Za-z0-9_]+$ ]] || fail_stop "that does not look like a GitHub token"
  write_env RELEASE_TRIGGER_TOKEN "$RELEASE_TRIGGER_TOKEN"
  unset RELEASE_TRIGGER_TOKEN
  note "Note the token's expiry date: when it lapses, the nightly release fails and sends a failure email."
else
  say "The token is set."
fi
ENV_FILE=$SERVER_ENV
pause

stage "Install the production units"
say "Deploy (:release), the nightly release trigger, pin sync, Caddy's config, backups, the drill, the failure hook and the egress firewall."
root "$REPO/ops/install.sh" production
pause

stage "First deploy"
docker manifest inspect ghcr.io/wispmoney/api:release >/dev/null 2>&1 ||
  fail_stop "no :release image yet: run the Release workflow once (gh workflow run release.yml --ref main), then run setup again"
root systemctl enable --now wisp-deploy-production.timer wisp-release-trigger.timer
say "The first deploy pulls the images and starts the stack (a few minutes):"
root systemctl start wisp-deploy-production.service
if bash -c "$HEALTH_WAIT"; then say "The app answers on the server."; else fail_stop "the app is not healthy: journalctl -u wisp-deploy-production.service -n 50"; fi
if curl -fsS -o /dev/null --max-time 15 "$APP_ORIGIN/api/health"; then say "And at $APP_ORIGIN."; else warn "$APP_ORIGIN does not answer yet (DNS or certificates); Caddy keeps retrying."; fi
pause

stage "Egress firewall"
say "Loads now and at every boot; it needs the stack's networks, which the first deploy created."
root systemctl enable --now wisp-api-egress.service
if systemctl is-active --quiet wisp-api-egress.service; then say "Loaded."; else warn "not active: journalctl -u wisp-api-egress.service"; fi
pause

stage "Backups, the drill and failure emails"
root systemctl enable --now wisp-backup.timer wisp-restore-drill.timer
say "One backup and one test restore now:"
root systemctl start wisp-backup.service
root systemctl start wisp-restore-drill.service
say "A test failure email to OPERATOR_ALERT_EMAIL, subject '[wisp] wizard-test failed on …':"
root systemctl start wisp-failure-email@wizard-test.service
pause "Arrived?"

stage "Next"
say "The server is at the production baseline, with an empty database."
step "A lost server's data comes back from Helsinki: docs/backups.md, Rebuilding the server from Helsinki."
note "Staging's feed (docs/staging-feed.md, Setting it up) needs the owner's account id, so it follows the restore."
pause
finish
}

# ── The production env file ───────────────────────────────────────────────

env_wizard() {
TOTAL_STAGES=7
ENV_FILE=$SERVER_ENV
banner "Wisp production env file"

stage "Fixed settings"
[[ -w $ENV_FILE ]] || fail_stop "$ENV_FILE must exist and belong to $USER (setup's Directories stage creates it)"
say "Wisp names and the public address."
write_env NODE_ENV production
write_env PORT 3000
write_env API_URL http://api:3000
write_env DB_USERNAME wisp
write_env DB_NAME wisp
write_env DB_SYNCHRONIZE false
write_env SESSION_REDIS_KEY wisp-session
write_env EMAIL_VERIFICATION_REDIS_KEY wisp-email-verification
write_env PASSWORD_RESET_REDIS_KEY wisp-password-reset
write_env WEB_BASE_URL "$APP_ORIGIN"
write_env ENABLE_BANKING_API_URL https://api.enablebanking.com
write_env ENABLE_BANKING_REDIRECT_URL "$APP_ORIGIN$CALLBACK_PATH"
write_env ENABLE_BANKING_PRIVATE_KEY_HOST_PATH "$SERVER_KEY"
default_env SESSION_EXPIRATION 30d
default_env EMAIL_VERIFICATION_EXPIRATION 24h
default_env PASSWORD_RESET_EXPIRATION 1h
default_env THROTTLE_TTL 1m
default_env THROTTLE_LIMIT 100
pause

stage "The server's own secrets"
say "A database password and a session secret of the server's own, generated once and never shown."
note "A new session secret logs every device out: each one logs in again."
if [[ -z $(_existing DB_PASSWORD || true) ]]; then write_env DB_PASSWORD "$(random_secret)"; else say "DB_PASSWORD is set (PostgreSQL keeps the first one: never change it here)."; fi
default_env SESSION_SECRET "$(random_secret)"
pause

stage "Enable Banking"
say "The same Enable Banking application as production's, so live sync carries on."
ask ENABLE_BANKING_APPLICATION_ID "Application ID (production's ENABLE_BANKING_APPLICATION_ID):"
[[ -n $ENABLE_BANKING_APPLICATION_ID ]] || fail_stop "the application ID is required"
write_env ENABLE_BANKING_APPLICATION_ID "$ENABLE_BANKING_APPLICATION_ID"
say "Stored bank sessions are encrypted with production's key: the server needs exactly that key."
while :; do
  ask_secret BANKING_SESSION_ENCRYPTION_KEY_B64 "BANKING_SESSION_ENCRYPTION_KEY_B64 (production's):"
  (($(base64 -d <<<"$BANKING_SESSION_ENCRYPTION_KEY_B64" 2>/dev/null | wc -c) == 32)) && break
  warn "that is not base64 of 32 bytes"
done
write_env BANKING_SESSION_ENCRYPTION_KEY_B64 "$BANKING_SESSION_ENCRYPTION_KEY_B64"
unset BANKING_SESSION_ENCRYPTION_KEY_B64
pause

stage "Email through Scaleway"
say "App and alert email go through Scaleway Transactional Email (smtp.tem.scaleway.com, STARTTLS)."
open_url "https://console.scaleway.com/transactional-email/domains"
step "Transactional Email → Domains → wispmoney.com → SMTP: the user is the project ID."
ask EMAIL_USERNAME "SMTP user (the Scaleway project ID):"
write_env EMAIL_USERNAME "$EMAIL_USERNAME"
step "IAM → API keys → an API key with Transactional Email rights: its secret key is the SMTP password."
ask_secret EMAIL_PASSWORD "SMTP password (the API key's secret key):"
[[ -n $EMAIL_PASSWORD ]] || fail_stop "the SMTP password is required"
write_env EMAIL_PASSWORD "$EMAIL_PASSWORD"
unset EMAIL_PASSWORD
ask EMAIL_FROM "Sender, a wispmoney.com address (\"Wisp\" <no-reply@wispmoney.com>):"
[[ $EMAIL_FROM == *@wispmoney.com* ]] || warn "Scaleway sends only from the verified domain, wispmoney.com"
write_env EMAIL_FROM "$EMAIL_FROM"
ask OPERATOR_ALERT_EMAIL "Where failure emails go (OPERATOR_ALERT_EMAIL):"
[[ $OPERATOR_ALERT_EMAIL == ?*@?*.?* ]] || fail_stop "an email address is required"
write_env OPERATOR_ALERT_EMAIL "$OPERATOR_ALERT_EMAIL"
pause

stage "Claude categorization and features"
say "Same choices as production's env file (ops/README.md describes each)."
for flag in AI_CATEGORIZATION_ENABLED AI_CATEGORIZATION_WEB_SEARCH_ENABLED MERCHANT_LOGOS_ENABLED FILE_IMPORT_ENABLED FILE_IMPORT_MAPPER_ENABLED; do
  ask_bool "$flag" "$flag"
  write_env "$flag" "${!flag}"
done
if [[ $AI_CATEGORIZATION_ENABLED == true || $MERCHANT_LOGOS_ENABLED == true || $FILE_IMPORT_MAPPER_ENABLED == true ]]; then
  ask_secret ANTHROPIC_API_KEY "ANTHROPIC_API_KEY:"
  [[ -n $ANTHROPIC_API_KEY ]] || fail_stop "these features need ANTHROPIC_API_KEY"
  write_env ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"
  unset ANTHROPIC_API_KEY
fi
if [[ $AI_CATEGORIZATION_ENABLED == true && $AI_CATEGORIZATION_WEB_SEARCH_ENABLED == true ]]; then
  ask_secret BRAVE_SEARCH_API_KEY "BRAVE_SEARCH_API_KEY:"
  [[ -n $BRAVE_SEARCH_API_KEY ]] || fail_stop "web search needs BRAVE_SEARCH_API_KEY"
  write_env BRAVE_SEARCH_API_KEY "$BRAVE_SEARCH_API_KEY"
  unset BRAVE_SEARCH_API_KEY
fi
if [[ $MERCHANT_LOGOS_ENABLED == true ]]; then
  ask_secret LOGO_DEV_SECRET_KEY "LOGO_DEV_SECRET_KEY (Enter to go without logo.dev):"
  [[ -z $LOGO_DEV_SECRET_KEY ]] || write_env LOGO_DEV_SECRET_KEY "$LOGO_DEV_SECRET_KEY"
  unset LOGO_DEV_SECRET_KEY
fi
pause

stage "Push notifications"
if [[ -n $(_existing WEB_PUSH_VAPID_PRIVATE_KEY || true) ]]; then
  say "The server has its VAPID key pair."
else
  say "A new VAPID key pair for $APP_ORIGIN, made with the API image's web-push and never shown."
  note "Devices allowed notifications with the old key pair; each turns them on again."
  if pair=$(docker run --rm --network none --entrypoint node ghcr.io/wispmoney/api:release \
    -e 'const k = require("web-push").generateVAPIDKeys(); console.log(k.publicKey + " " + k.privateKey)' 2>/dev/null) &&
    read -r vapid_public vapid_private <<<"$pair" && [[ -n ${vapid_private:-} ]]; then
    write_env WEB_PUSH_VAPID_PUBLIC_KEY "$vapid_public"
    write_env WEB_PUSH_VAPID_PRIVATE_KEY "$vapid_private"
  else
    warn "could not generate one here; paste a pair from npx web-push generate-vapid-keys"
    ask WEB_PUSH_VAPID_PUBLIC_KEY "Public key:"
    write_env WEB_PUSH_VAPID_PUBLIC_KEY "$WEB_PUSH_VAPID_PUBLIC_KEY"
    ask_secret WEB_PUSH_VAPID_PRIVATE_KEY "Private key:"
    write_env WEB_PUSH_VAPID_PRIVATE_KEY "$WEB_PUSH_VAPID_PRIVATE_KEY"
  fi
  unset pair vapid_public vapid_private WEB_PUSH_VAPID_PRIVATE_KEY
fi
default_env WEB_PUSH_VAPID_SUBJECT "mailto:$(_existing OPERATOR_ALERT_EMAIL)"
pause

stage "Check"
missing=()
for key in NODE_ENV PORT API_URL WEB_BASE_URL DB_USERNAME DB_PASSWORD DB_NAME DB_SYNCHRONIZE SESSION_SECRET \
  SESSION_EXPIRATION SESSION_REDIS_KEY ENABLE_BANKING_API_URL ENABLE_BANKING_APPLICATION_ID ENABLE_BANKING_REDIRECT_URL \
  ENABLE_BANKING_PRIVATE_KEY_HOST_PATH BANKING_SESSION_ENCRYPTION_KEY_B64 EMAIL_USERNAME EMAIL_PASSWORD EMAIL_FROM \
  OPERATOR_ALERT_EMAIL EMAIL_VERIFICATION_EXPIRATION EMAIL_VERIFICATION_REDIS_KEY PASSWORD_RESET_EXPIRATION \
  PASSWORD_RESET_REDIS_KEY THROTTLE_TTL THROTTLE_LIMIT; do
  [[ -n $(_existing "$key" || true) ]] || missing+=("$key")
done
((${#missing[@]} == 0)) || fail_stop "still missing: ${missing[*]}"
say "Every setting the API needs is in $ENV_FILE."
note "The API reads it when it starts: a running stack picks changes up at the next deploy or restart."
pause
finish
}

run_wizard() {
case ${1:-} in
  setup) setup_wizard ;;
  env) env_wizard ;;
  *)
    echo "usage: $0 setup | env   (docs/new-host.md)" >&2
    exit 2
    ;;
esac
}

run_wizard "$@"; exit
